script:
def tree(path, depth, out):
    if depth == 0:
        return
    for name in repo.list(path):
        p = name if path == "." else path + "/" + name
        out.append(p)
        if name.endswith("/"):
            tree(p.rstrip("/"), depth - 1, out)

out = []
tree(".", 4, out)
return out

